try {
  const w = $('Growth Webhook').first().json || {};
  const b = w.body || w;
  const action = String(b.action || '').toLowerCase();
  const ACTIONS = ["queue_status","founder_start","founder_add_question","founder_answer","founder_cancel","founder_status","resources_list","resource_register","resource_retire","rss_pending","rss_mark","rss_status","competitors_list","competitor_report","intel_latest","signals_candidates","resource_opportunity","resource_backlog"];
  if (!ACTIONS.includes(action)) throw new Error('action inválida: usa ' + ACTIONS.join(' | '));
  const isUuid = (v) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(v || ''));
  const slugOk = (v) => /^[a-z0-9]+(-[a-z0-9]+)*$/.test(String(v || ''));
  const sb = 'https://uwquwjmiofixzugttals.supabase.co/rest/v1/';
  const reads = [];
  const add = (key, path) => reads.push({ key, url: sb + path });
  add('config', 'content_config?id=eq.1&select=*');
  const iid = b.interview_id;
  if (iid !== undefined && iid !== null && iid !== '' && !isUuid(iid)) throw new Error('interview_id inválido');
  let probe = null;
  if (action === 'queue_status') {
    add('pending', 'content_pieces?icp_pack_id=eq.0ba54785-bff0-4a2d-a397-64e697d34e38&status=eq.in_review&is_test=eq.false&select=id,channel,topic');
    add('candidates', 'content_sources?icp_pack_id=eq.0ba54785-bff0-4a2d-a397-64e697d34e38&signal_status=eq.candidate&select=id,title,signal_type,signal_score&order=signal_score.desc&limit=20');
    add('waiting_render', 'content_pieces?icp_pack_id=eq.0ba54785-bff0-4a2d-a397-64e697d34e38&status=eq.drafted&is_test=eq.false&select=id,channel,format,topic');
    add('new_items', 'content_feed_items?status=eq.new&select=id&limit=400');
    add('interviews', 'founder_interviews?status=in.(asked,answered)&is_test=eq.false&select=id,status,asked_at&order=asked_at.desc&limit=5');
  } else if (action === 'founder_start') {
    add('questions', 'founder_questions?status=eq.available&select=*&order=priority.desc&limit=30');
    add('open', 'founder_interviews?status=in.(asked,answered)&is_test=eq.' + (b.test === true ? 'true' : 'false') + '&select=*&order=asked_at.desc&limit=1');
  } else if (action === 'founder_add_question') {
    add('questions', 'founder_questions?select=id,question&limit=500');
  } else if (action === 'founder_answer' || action === 'founder_cancel') {
    add('interview', iid ? 'founder_interviews?id=eq.' + iid + '&select=*' : 'founder_interviews?status=eq.asked&is_test=eq.' + (b.test === true ? 'true' : 'false') + '&select=*&order=asked_at.desc&limit=1');
  } else if (action === 'founder_status') {
    add('interviews', 'founder_interviews?is_test=eq.false&select=id,status,question,answer_source,piece_ids,asked_at,answered_at&order=asked_at.desc&limit=10');
  } else if (action === 'resources_list' || action === 'resource_opportunity' || action === 'resource_backlog') {
    add('resources', 'content_resources?select=*&order=created_at.desc&limit=200');
  } else if (action === 'resource_register' || action === 'resource_retire') {
    const slug = String(b.slug || (b.resource || {}).slug || '').trim();
    if (!slugOk(slug)) throw new Error('slug inválido (kebab-case)');
    add('resource', 'content_resources?slug=eq.' + slug + '&select=*');
    const st = String(b.status || (b.resource || {}).status || 'draft');
    const url = String(b.url || (b.resource || {}).url || '');
    if (action === 'resource_register' && st === 'active' && /^https:\/\//.test(url)) probe = url;
  } else if (action === 'rss_pending') {
    const since = new Date(Date.now() - 10 * 86400000).toISOString();
    add('items_dated', 'content_feed_items?status=eq.new&published_at=gte.' + since + '&select=*&order=relevance.desc,published_at.desc&limit=80');
    add('items_undated', 'content_feed_items?status=eq.new&published_at=is.null&select=*&order=relevance.desc,ingested_at.desc&limit=40');
    add('feeds', 'content_feeds?select=id,slug,name,topic,priority&limit=100');
    add('pending', 'content_pieces?icp_pack_id=eq.0ba54785-bff0-4a2d-a397-64e697d34e38&status=eq.in_review&is_test=eq.false&select=id');
  } else if (action === 'rss_status') {
    add('feeds', 'content_feeds?select=*&order=priority.desc&limit=100');
    add('new_items', 'content_feed_items?status=eq.new&select=id,feed_slug&limit=500');
  } else if (action === 'competitors_list') {
    add('competitors', 'content_competitors?select=*&order=created_at.asc&limit=50');
    add('reports', 'content_intel_reports?select=id,run_id,created_at,competitors_scanned,signals_submitted,report&order=created_at.desc&limit=1');
  } else if (action === 'competitor_report') {
    const rid = String((b.report || {}).run_id || b.run_id || '');
    add('existing', 'content_intel_reports?run_id=eq.' + encodeURIComponent(rid.slice(0, 80)) + '&select=id,run_id');
    add('competitors', 'content_competitors?select=id,slug,name&limit=50');
  } else if (action === 'signals_candidates') {
    add('signals', 'content_sources?icp_pack_id=eq.0ba54785-bff0-4a2d-a397-64e697d34e38&signal_status=eq.candidate&select=id,source_key,title,url,summary,signal_type,signal_score,signal,evidence,source_date,created_at&order=signal_score.desc&limit=15');
    add('pending', 'content_pieces?icp_pack_id=eq.0ba54785-bff0-4a2d-a397-64e697d34e38&status=eq.in_review&is_test=eq.false&select=id');
    add('recent', 'content_pieces?icp_pack_id=eq.0ba54785-bff0-4a2d-a397-64e697d34e38&is_test=eq.false&select=topic,channel,status,hook:piece->>hook&order=created_at.desc&limit=30');
  } else if (action === 'intel_latest') {
    add('reports', 'content_intel_reports?select=*&order=created_at.desc&limit=1');
  }
  return [{ json: { action, b: { ...b, action: undefined }, reads, probe } }];
} catch (e) { return [{ json: { fatal: String((e && e.message) || e) } }]; }

function growthCheckAnswer(text) {
  const t = String(text || '').trim();
  if (t.length < 120) return { ok: false, reason: 'respuesta_muy_corta_minimo_120_caracteres', length: t.length };
  if (t.length > 8000) return { ok: false, reason: 'respuesta_muy_larga_maximo_8000', length: t.length };
  return { ok: true, reason: null, length: t.length };
}

function growthFounderEvidence(answer, piece) {
  const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9ñ ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const a = norm(answer);
  const quotes = [];
  ((piece && piece.sources) || []).forEach((s) => { if (s && s.kind === 'real_work') (Array.isArray(s.evidence) ? s.evidence : []).forEach((e) => { if (e && typeof e.quote === 'string' && e.quote.trim()) quotes.push(e.quote.trim()); }); });
  const unmatched = quotes.filter((q) => norm(q).length < 15 || !a.includes(norm(q)));
  if (!quotes.length) return { ok: false, reason: 'founder_sin_cita_de_la_respuesta', matched: 0, unmatched: [] };
  if (unmatched.length) return { ok: false, reason: 'founder_cita_no_esta_en_la_respuesta', matched: quotes.length - unmatched.length, unmatched: unmatched.map((q) => q.slice(0, 60)) };
  return { ok: true, reason: null, matched: quotes.length, unmatched: [] };
}

function growthGovernor(o) {
  const x = o || {};
  const max = Number.isFinite(Number(x.max)) && Number(x.max) > 0 ? Number(x.max) : 6;
  const pending = Math.max(0, Number(x.pending) || 0);
  const origin = ['autonomous', 'explicit', 'founder_interview'].includes(x.origin) ? x.origin : 'explicit';
  const full = pending >= max;
  if (!full) return { allowed: true, warning: null, reason: null, pending, max, origin };
  if (origin === 'autonomous') return { allowed: false, warning: null, reason: 'cola_llena', pending, max, origin };
  return { allowed: true, warning: 'cola_llena_por_orden_explicita', reason: null, pending, max, origin };
}

function growthNorm(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9ñ ]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function growthNormIntel(report) {
  const errors = [];
  const x = report && typeof report === 'object' ? report : {};
  const str = (v, m) => (typeof v === 'string' ? v.trim().slice(0, m || 300) : '');
  const arr = (v, m, len) => (Array.isArray(v) ? v.map((i) => str(i, len || 240)).filter(Boolean).slice(0, m || 10) : []);
  const isUrl = (u) => /^https?:\/\/[^\s]+$/i.test(String(u || ''));
  const runId = str(x.run_id, 80);
  if (runId.length < 6) errors.push('run_id_obligatorio');
  const comps = (Array.isArray(x.competitors) ? x.competitors : []).map((c) => {
    const slug = str(c && c.slug, 60);
    const pages = (Array.isArray(c && c.pages_read) ? c.pages_read : []).map((u) => String(u || '').trim()).filter(isUrl).slice(0, 12);
    if (!slug) errors.push('competidor_sin_slug');
    else if (!pages.length) errors.push('competidor_sin_paginas_leidas:' + slug);
    return { slug, pages_read: pages, recent_topics: arr(c && c.recent_topics, 10), formats: arr(c && c.formats, 8, 120), hooks: arr(c && c.hooks, 8), offers: arr(c && c.offers, 8), resources: arr(c && c.resources, 8), repeated_messages: arr(c && c.repeated_messages, 8) };
  });
  if (!comps.length) errors.push('sin_competidores');
  const saturated = arr(x.saturated_topics, 10);
  const gaps = arr(x.gaps, 10);
  const angles = (Array.isArray(x.own_angles) ? x.own_angles : []).map((a) => ({ angle: str(a && a.angle, 300), why: str(a && a.why, 300), channel_suggestion: ['instagram', 'linkedin_page', 'linkedin_profile'].includes(a && a.channel_suggestion) ? a.channel_suggestion : null })).filter((a) => a.angle).slice(0, 8);
  if (!gaps.length && !angles.length) errors.push('sin_huecos_ni_angulos_propios');
  if (angles.some((a) => !a.why)) errors.push('angulo_propio_sin_porque');
  return { ok: errors.length === 0, errors, value: { run_id: runId, competitors: comps, saturated_topics: saturated, gaps, own_angles: angles, notes: str(x.notes, 600) } };
}

function growthPickQuestion(questions, openInterview, nowMs) {
  const now = Number(nowMs) || Date.now();
  if (openInterview && openInterview.status === 'asked' && now - Date.parse(openInterview.asked_at) < 72 * 3600000) return { reuse: true, interview: openInterview, question: null };
  const avail = (Array.isArray(questions) ? questions : []).filter((q) => q && q.status === 'available');
  avail.sort((a, b) => (b.priority || 0) - (a.priority || 0) || String(a.created_at || '').localeCompare(String(b.created_at || '')));
  return { reuse: false, interview: null, question: avail[0] || null };
}

function growthResourceRank(resources, query, opts) {
  const o = opts || {};
  const stop = new Set(['de', 'la', 'el', 'los', 'las', 'un', 'una', 'para', 'por', 'con', 'que', 'en', 'y', 'o', 'a', 'del', 'al', 'mi', 'tu', 'su', 'se', 'es', 'como', 'qué', 'cómo']);
  const toks = (t) => growthNorm(t).split(' ').filter((w) => w.length > 2 && !stop.has(w));
  const q = toks(query);
  const list = (Array.isArray(resources) ? resources : []).filter((r) => r && (r.status === 'active' || (o.includeDraft && r.status === 'draft')));
  const scored = list.map((r) => {
    const name = toks(r.name), topic = toks(r.topic), problem = toks(r.problem), aud = toks(r.audience);
    let s = 0;
    q.forEach((w) => {
      if (name.some((n) => n.startsWith(w) || w.startsWith(n))) s += 3;
      if (topic.some((n) => n.startsWith(w) || w.startsWith(n))) s += 3;
      if (problem.some((n) => n.startsWith(w) || w.startsWith(n))) s += 2;
      if (aud.some((n) => n.startsWith(w) || w.startsWith(n))) s += 1;
    });
    return { ...r, match_score: s };
  }).filter((r) => (q.length ? r.match_score > 0 : true));
  scored.sort((a, b) => b.match_score - a.match_score || String(b.created_at || '').localeCompare(String(a.created_at || '')));
  return scored.slice(0, o.limit || 5);
}

function growthUtmUrl(url, p) {
  const o = p || {};
  const src = String(o.channel || '').startsWith('linkedin') ? 'linkedin' : o.channel === 'instagram' ? 'instagram' : 'social';
  const base = String(url || '').split('#')[0];
  const sep = base.includes('?') ? '&' : '?';
  const enc = (v) => encodeURIComponent(String(v || '').slice(0, 60));
  return base + sep + 'utm_source=' + src + '&utm_medium=organic_social&utm_campaign=' + enc(o.slug) + (o.ideaKey ? '&utm_content=' + enc(o.ideaKey) : '');
}

function growthValidateResource(r) {
  const errors = [];
  const x = r && typeof r === 'object' ? r : {};
  const str = (v) => (typeof v === 'string' ? v.trim() : '');
  const TYPES = ['guia', 'checklist', 'plantilla', 'diagnostico', 'prompt', 'documento', 'comparativa', 'caso', 'herramienta', 'pagina'];
  const MODES = ['resource_link', 'dm', 'diagnostic'];
  const slug = str(x.slug);
  if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(slug) || slug.length > 80) errors.push('slug_invalido');
  const name = str(x.name);
  if (name.length < 5 || name.length > 120) errors.push('nombre_fuera_de_rango');
  if (!TYPES.includes(x.type)) errors.push('tipo_invalido');
  const topic = str(x.topic);
  if (topic.length < 3 || topic.length > 120) errors.push('tema_fuera_de_rango');
  const problem = str(x.problem);
  if (problem.length < 20 || problem.length > 400) errors.push('problema_debe_describir_que_resuelve_20_400');
  const mode = x.cta_mode || 'resource_link';
  if (!MODES.includes(mode)) errors.push('cta_mode_invalido');
  const ctaCopy = str(x.cta_copy);
  if (ctaCopy.length > 240) errors.push('cta_copy_largo');
  const url = str(x.url);
  const host = (/^https:\/\/([^/?#]+)/i.exec(url) || [])[1];
  if (!host) errors.push('url_https_obligatoria');
  else if (!/^(www\.)?atacamalabs\.cl$/i.test(host) && !(x.metadata && x.metadata.external === true)) errors.push('url_fuera_de_atacamalabs_cl');
  const status = x.status || 'draft';
  if (!['draft', 'active', 'retired'].includes(status)) errors.push('estado_invalido');
  const value = { slug, name, type: x.type, topic, audience: str(x.audience) || null, problem, cta_mode: mode, cta_copy: ctaCopy || null, url, status, metadata: x.metadata && typeof x.metadata === 'object' ? x.metadata : {}, created_by: str(x.created_by) || 'hermes' };
  return { ok: errors.length === 0, errors, value };
}

function rfAssess(input, resources) {
  const x = input && typeof input === 'object' ? input : {};
  const list = Array.isArray(resources) ? resources : [];
  const type = String(x.editorial_type || '');
  const query = String(x.topic || '') + ' ' + String(x.summary || '');
  const NO_CTA = ['opinion', 'founder', 'build_in_public', 'news_explainer', 'market_signal'];
  if (NO_CTA.includes(type)) return { action: 'none', reason: 'Una pieza de tipo ' + type + ' (reflexión, noticia, posicionamiento) no necesita recurso: se publica sin CTA comercial.', matches: [] };
  if (!String(x.topic || '').trim()) return { action: 'none', reason: 'Falta el tema para evaluar un recurso.', matches: [] };
  const ranked = growthResourceRank(list.filter((r) => r && r.status !== 'retired'), query, { includeDraft: true, limit: 5 });
  const matches = ranked.map((r) => ({ id: r.id, slug: r.slug, name: r.name, status: r.status, match_score: r.match_score }));
  const best = ranked[0];
  // Reutilizar exige que la pieza cubra casi todo el nombre del recurso (no basta compartir palabras genéricas como «proceso» o «automatizar»).
  const nameToks = best ? String(best.name || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]+/g, ' ').split(' ').filter((w) => w.length > 3) : [];
  const qToks = query.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]+/g, ' ').split(' ').filter((w) => w.length > 3);
  const coverage = nameToks.length ? nameToks.filter((w) => qToks.some((t) => t.startsWith(w.slice(0, 5)) || w.startsWith(t.slice(0, 5)))).length / nameToks.length : 0;
  if (best && best.match_score >= 9 && coverage >= 0.75) {
    if (best.status === 'active') return { action: 'reuse', reason: 'Ya existe un recurso activo que resuelve el mismo problema («' + best.name + '»): se reutiliza, no se crea otro.', resource: { id: best.id, slug: best.slug, name: best.name, url: best.url, cta_mode: best.cta_mode }, matches };
    return { action: 'backlog', reason: '«' + best.name + '» ya está en la backlog como borrador (falta construir su página): no se duplica; la pieza sale sin recurso por ahora.', resource: { id: best.id, slug: best.slug, name: best.name, status: best.status }, matches };
  }
  const toks = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]+/g, ' ').split(' ').filter((w) => w.length > 3);
  const q = toks(query);
  const have = new Set(list.map((r) => r && r.slug));
  const fmts = rfFormats();
  const cands = rfBacklog().filter((c) => !have.has(c.slug) && c.fits.includes(type || 'educational')).map((c) => {
    const ct = toks(c.name + ' ' + c.topic + ' ' + c.problem);
    const hit = q.filter((w) => ct.some((t) => t.startsWith(w.slice(0, 5)) || w.startsWith(t.slice(0, 5)))).length;
    return { c, hit };
  }).filter((e) => e.hit >= 2).sort((a, b) => b.hit - a.hit || b.c.priority - a.c.priority);
  if (cands.length) {
    const c = cands[0].c;
    return { action: 'propose', reason: 'No hay un recurso para este tema y la backlog tiene uno que encaja («' + c.name + '»): puede proponerse (queda en borrador hasta que exista su página).', candidate: { slug: c.slug, name: c.name, format: c.format, type: fmts[c.format].type, interactive: fmts[c.format].interactive, effort: fmts[c.format].effort, differentiator: c.differentiator }, matches };
  }
  return { action: 'none', reason: 'No hay un recurso que aporte a este tema y no corresponde a una necesidad de la backlog: no se crea uno solo para tener un CTA.', matches };
}

function rfAuthority(d) {
  const x = d && typeof d === 'object' ? d : {};
  const pieces = Array.isArray(x.pieces) ? x.pieces : [];
  const metrics = Array.isArray(x.metrics) ? x.metrics : [];
  const resources = Array.isArray(x.resources) ? x.resources : [];
  const leads = Array.isArray(x.leads) ? x.leads : [];
  const bySlug = {};
  resources.forEach((r) => { bySlug[r.id] = r.slug; });
  const leadsFor = (slug) => (slug ? leads.filter((l) => String(l.campaign || '') === slug || String(l.source_page || '').includes('/recursos/' + slug) || String(l.source_page || '').includes('recursos-' + slug)).length : 0);
  const rank = { '24h': 1, '72h': 2, '7d': 3 };
  const latest = {};
  metrics.filter((m) => m && m.content_piece_id && (m.status === undefined || m.status === 'ok' || m.status === 'partial')).forEach((m) => {
    const cur = latest[m.content_piece_id];
    if (!cur || (rank[m.metric_window] || 0) >= (rank[cur.metric_window] || 0)) latest[m.content_piece_id] = m;
  });
  const rows = [];
  pieces.filter((p) => p && !p.is_test && p.status === 'published').forEach((p) => {
    const m = latest[p.id];
    if (!m) { rows.push({ id: p.id, title: String(p.topic || '').slice(0, 90), channel: p.channel, editorial_type: p.editorial_type || null, klass: 'sin_datos', attention: null, conversation: null, leads: 0, authority_score: null }); return; }
    const likes = Number(m.likes) || 0, comments = Number(m.comments) || 0, shares = Number(m.shares) || 0;
    const attention = likes + comments + shares, conversation = comments * 2 + shares * 3;
    const slug = p.resource_id ? bySlug[p.resource_id] : null;
    const nLeads = leadsFor(slug);
    const score = conversation + (p.resource_id ? 2 : 0) + nLeads * 15;
    let klass = 'mixta';
    if (nLeads > 0 || (conversation >= 3 && conversation >= attention * 0.5)) klass = 'autoridad';
    else if (attention >= 10 && conversation < attention * 0.25) klass = 'atencion';
    rows.push({ id: p.id, title: String(p.topic || '').slice(0, 90), channel: p.channel, editorial_type: p.editorial_type || null, klass, attention, conversation, leads: nLeads, authority_score: score, has_resource: Boolean(p.resource_id) });
  });
  const measured = rows.filter((r) => r.klass !== 'sin_datos');
  const count = (k) => measured.filter((r) => r.klass === k).length;
  const byType = {};
  measured.forEach((r) => { const t = r.editorial_type || 'sin_tipo'; (byType[t] = byType[t] || []).push(r.authority_score); });
  const types = Object.keys(byType).map((t) => ({ type: t, pieces: byType[t].length, avg_authority: Math.round((byType[t].reduce((a, b) => a + b, 0) / byType[t].length) * 10) / 10 })).sort((a, b) => b.avg_authority - a.avg_authority);
  const learn = [];
  if (types.length >= 2 && types[0].avg_authority > types[types.length - 1].avg_authority) learn.push('Con los datos actuales, las piezas de tipo «' + types[0].type + '» generan más conversación que las de «' + types[types.length - 1].type + '» (muestra chica: ' + measured.length + ' piezas medidas).');
  const att = measured.filter((r) => r.klass === 'atencion');
  if (att.length) learn.push(att.length + ' pieza(s) llamaron la atención (likes) sin generar conversación: no necesariamente sirven para autoridad.');
  const aut = measured.filter((r) => r.klass === 'autoridad').sort((a, b) => b.authority_score - a.authority_score);
  return {
    pieces_measured: measured.length, pieces_without_data: rows.length - measured.length,
    attention_only: count('atencion'), authority: count('autoridad'), mixed: count('mixta'),
    top_authority: aut.slice(0, 3).map((r) => ({ title: r.title, channel: r.channel, editorial_type: r.editorial_type, score: r.authority_score, leads: r.leads })),
    by_editorial_type: types, learn,
    measurable: ['likes, comentarios y compartidos por publicación (GHL)', 'piezas con recurso asociado', 'leads cuyo origen es /recursos/<slug> o cuya campaña es el slug del recurso'],
